// ── Vérifications ───────────────────────────────────────────────────────────
const ids = new Set(registre.map((r) => r.id));
const cids = new Set(C.map((c) => c.id));
const pb = [];
for (const r of registre) for (const p of r.problemes) if (!cids.has(p)) pb.push(r.id + " → constat inconnu " + p);
for (const c of C) {
  for (const s of c.surfaces) if (!ids.has(s)) pb.push(c.id + " → surface inconnue " + s);
  for (const v of c.visuels) if (!fs.existsSync(path.join(CAPT, v + "--m390.json"))) pb.push(c.id + " → visuel sans capture " + v);
}
for (const r of registre) {
  const aCapture = fs.existsSync(path.join(CAPT, r.id + "--m390.json"));
  if (r.visuel !== "aucun" && !aCapture) pb.push(r.id + " → visuel " + r.visuel + " mais aucune capture");
  if (r.visuel === "avant-apres") { const f = JSON.parse(fs.readFileSync(path.join(CAPT, r.id + "--m390.json"), "utf8")); if (!f.apres) pb.push(r.id + " → avant-apres sans après"); }
}
fs.writeFileSync(path.join(AUDIT, "donnees", "domaines", "entree.json"), JSON.stringify(out, null, 2) + "\n");
const compte = (k, v) => registre.filter((r) => r[k] === v).length;
console.log(JSON.stringify({
  surfaces: registre.length, observe: compte("observation", "observe"), simule: compte("observation", "simule"), code: compte("observation", "code"), inaccessible: compte("observation", "inaccessible"),
  avantApres: compte("visuel", "avant-apres"), avant: compte("visuel", "avant"), aucun: compte("visuel", "aucun"),
  aConserver: compte("verdict", "a-conserver"), aAmeliorer: compte("verdict", "a-ameliorer"), aVerifier: compte("verdict", "a-verifier"),
  constats: C.length, P0: C.filter((c) => c.priorite === "P0").length, P1: C.filter((c) => c.priorite === "P1").length, P2: C.filter((c) => c.priorite === "P2").length, P3: C.filter((c) => c.priorite === "P3").length,
  problemes: pb,
}, null, 1));
